        "company": "Viking은 유럽 강 크루즈와 해양 크루즈를 운영하는 여행 회사로, 승객 운임과 선내 매출로 돈을 번다.",
        "volumeExplanation": "11월 17일 2027년 예약 현황이 주목되며 Barron's에 따르면 실적 미달에도 주가가 오른 것으로 분석되었습니다.",
